const f = $('GEO Form').first().json || {};
const body = { website_url: f['Website URL'], brand_name: f['Brand Name'], tier: f['Tier'], market: f['Market'], language: f['Language'], prompt_count: f['Number of prompts'] };
const rawUrl = String(body.website_url || '').trim();
if (!rawUrl) throw new Error('website_url is required');
const website = /^https?:\/\//i.test(rawUrl) ? rawUrl : 'https://' + rawUrl;
const host = website.replace(/^https?:\/\//i, '').split(/[\/?#:]/)[0].replace(/^www\./i, '').toLowerCase();
if (!host || host.indexOf('.') < 0) throw new Error('Invalid website URL: ' + rawUrl);

const html = String($('Fetch Website').first().json.body.response.body || '');
const clean = html.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ');
const title = ((clean.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1] || '').replace(/\s+/g, ' ').trim();
const meta = (clean.match(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)/i) || [])[1] || '';
const text = clean.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 7000);

const tierGuide = {
  'Tier 1: Executive & VIP Corporate Gifting': 'Buyers: HR heads, PAs, procurement, C-suite assistants. Topics: luxury corporate gifts, Ramadan/Eid/National Day gifting, VIP client gifts, branded premium hampers, bulk orders.',
  'Tier 2: Hospitality, Majlis & Boutique Hotel': 'Buyers: hotel GMs, F&B/guest-experience managers, majlis owners, interior buyers. Topics: guest amenities, in-room experience, majlis hospitality, boutique hotel experience, Arabic hospitality.',
  'Tier 3: Healthcare, Spas & Premium Medical Clinics': 'Buyers: clinic/spa owners, procurement, patient-experience managers. Topics: spa products, clinic ambience, premium patient experience, wellness retail.',
  'Tier 4: Corporate Wellness & Interior Architecture': 'Buyers: facility managers, interior architects, HR wellbeing leads, developers. Topics: office wellness, brand experience in interiors, lobby design, fit-out specifications.'
};
const tier = String(body.tier || '');
if (!tierGuide[tier]) throw new Error('Unknown tier: ' + tier);
const tierNum = (tier.match(/Tier\s*(\d)/) || [])[1] || '0';

const MARKETS = ['KSA', 'UAE', 'GCC', 'Global'];
const LANGS = ['English', 'Arabic', 'English + Arabic'];
const market = MARKETS.includes(body.market) ? body.market : 'KSA';
const language = LANGS.includes(body.language) ? body.language : 'English';
const n = [10, 25].includes(parseInt(body.prompt_count, 10)) ? parseInt(body.prompt_count, 10) : 10;
const locationHint = { KSA: 'Riyadh, Jeddah, Dammam, Saudi Arabia', UAE: 'Dubai, Abu Dhabi, UAE', GCC: 'GCC countries (KSA, UAE, Qatar, Kuwait, Bahrain, Oman)', Global: 'international / no specific country' }[market];

let brand = String(body.brand_name || '').trim() || title.split(/[|\-–—:]/)[0].trim() || host;
const runId = Date.now().toString(36);

// Slots: fixed category mix, interleaved, with deterministic language / segment / priority
const ORDER = ['Brand Direct Queries', 'KSA Category Intent', 'Executive Gifting', 'Problem-Solution'];
const cBrand = Math.round(n * 0.2), cCat = Math.round(n * 0.3), cExec = Math.round(n * 0.2);
const counts = [cBrand, cCat, cExec, n - cBrand - cCat - cExec];
const pools = ORDER.map((c, i) => Array(counts[i]).fill(c));
const cats = [];
while (cats.length < n) { for (const p of pools) { if (p.length) cats.push(p.shift()); } }
const SEG = { 'Brand Direct Queries': 'Brand', 'KSA Category Intent': 'Category benchmark', 'Executive Gifting': 'Non-brand', 'Problem-Solution': 'Non-brand' };
const high = Math.ceil(n * 0.4), med = Math.ceil(n * 0.4);
const slots = cats.map((c, i) => ({
  slot: i + 1,
  prompt_category: c,
  segment: SEG[c],
  language: language === 'English + Arabic' ? (i % 2 === 0 ? 'English' : 'Arabic') : language,
  priority: i < high ? 'High' : (i < high + med ? 'Medium' : 'Long-term')
}));

const system = 'You are a GEO (Generative Engine Optimization) strategist for B2B and premium brands in the Gulf region. Use only facts found in the supplied website content. Where a fact is missing write "[TO VERIFY]". Never invent client names, prices, statistics, certifications or competitor company names. Return ONLY valid JSON, no markdown.';

const user = `BRAND: ${brand}
WEBSITE: ${website}
SITE TITLE: ${title}
META DESCRIPTION: ${meta}
SITE CONTENT (excerpt): ${text || '[site content could not be read; rely on brand name and URL and mark unknowns as [TO VERIFY]]'}

SELECTED TIER: ${tier}
TIER GUIDE: ${tierGuide[tier]}
MARKET: ${market} (${locationHint})
LANGUAGE SELECTION: ${language}

TASK
A) "profile": short factual summary of the business from the site.
B) "opportunities": exactly 3 distinct buyer opportunity themes for this tier in this market. "competitor" must describe competitor TYPES (e.g. "local boutique suppliers"), not company names.
C) "keywords": exactly ${n} items, one per slot below, in the same order. For each slot write one natural search keyword/phrase (3-8 words) in that slot's language, matching the slot's prompt_category:
 - Brand Direct Queries: includes the brand name.
 - KSA Category Intent: category benchmark phrase with a ${market} location, no brand name (adapt the location to the market).
 - Executive Gifting: decision-maker / VIP / seasonal-cultural angle, no brand name.
 - Problem-Solution: a buyer problem or need, no brand name.
 "opportunity_index" is 1, 2 or 3 (which opportunity it belongs to). Vary keyword_intent and icp_search_type across items.

SLOTS: ${JSON.stringify(slots)}

Return JSON exactly in this shape:
{"profile":{"summary":"","offerings":[""],"audience":"","differentiators":[""],"gaps":[""]},
"opportunities":[{"theme":"","buyer_intent":"","audience":"","search_query":"","seasonal":"","cultural":"","competitor":"","gap":""}],
"keywords":[{"slot":1,"opportunity_index":1,"keyword":"","keyword_intent":"Informational|Commercial|Transactional","icp_search_type":"Commercial|Seasonal|Cultural|Comparison|Direct answer","topic_cluster":"","suggested_blog_topic":""}]}`;

const OPENAI_MODEL = 'gpt-4o-mini'; // change here if you prefer another OpenAI model
const openai_body = { model: OPENAI_MODEL, temperature: 0.7, max_tokens: 6000, response_format: { type: 'json_object' },
  messages: [{ role: 'system', content: system }, { role: 'user', content: user }] };

return [{ json: {
  run_id: runId, brand, website, host, tier, tierNum, market, language, n, slots, locationHint,
  openai_body,
  body: {
    systemInstruction: { parts: [{ text: system }] },
    contents: [{ role: 'user', parts: [{ text: user }] }],
    generationConfig: { temperature: 0.7, maxOutputTokens: 16000, responseMimeType: 'application/json', thinkingConfig: { thinkingLevel: 'low' } }
  }
}}];

const ctx = $('Build Analysis Request').first().json;

function readJson(res, label) {
  const cand = (res.candidates || [])[0] || {};
  const txt = res.choices ? String(((res.choices[0] || {}).message || {}).content || '') : ((cand.content || {}).parts || []).map(p => p.text || '').join('');
  if (!txt) throw new Error(label + ': Gemini returned no text. finishReason=' + (cand.finishReason || 'n/a') + ' feedback=' + JSON.stringify(res.promptFeedback || {}));
  const s = txt.replace(/```json|```/g, '').trim();
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a < 0 || b < 0) throw new Error(label + ': no JSON found in response');
  try { return JSON.parse(s.slice(a, b + 1)); }
  catch (e) { throw new Error(label + ': invalid JSON (' + (cand.finishReason || '') + ') ' + e.message); }
}
const pick = (v, list, def) => list.find(x => x.toLowerCase() === String(v || '').toLowerCase()) || def;
const str = v => (v == null ? '' : String(v));

const data = readJson($input.first().json, 'Analysis');
const opps = (data.opportunities || []).slice(0, 3);
if (!opps.length) throw new Error('Analysis: no opportunities returned');

const opportunities = opps.map((o, i) => ({
  opportunity_id: `${ctx.run_id}-O${i + 1}`,
  theme: str(o.theme), buyer_intent: str(o.buyer_intent), audience: str(o.audience),
  search_query: str(o.search_query), seasonal: str(o.seasonal), cultural: str(o.cultural),
  competitor: str(o.competitor), gap: str(o.gap)
}));

const INTENTS = ['Informational', 'Commercial', 'Transactional'];
const ICPS = ['Commercial', 'Seasonal', 'Cultural', 'Comparison', 'Direct answer'];
const rawKw = data.keywords || [];
const slug = (ctx.brand.replace(/[^A-Za-z0-9]/g, '').toUpperCase().slice(0, 8)) || ctx.host.split('.')[0].replace(/[^A-Za-z0-9]/g, '').toUpperCase().slice(0, 8) || 'BRAND';
const CATCODE = { 'Brand Direct Queries': 'BRAND', 'KSA Category Intent': 'CAT', 'Executive Gifting': 'EXEC', 'Problem-Solution': 'PROB' };

const keywords = ctx.slots.map((s, i) => {
  const k = rawKw.find(x => Number(x.slot) === s.slot) || rawKw[i] || {};
  const oi = Math.min(Math.max(parseInt(k.opportunity_index, 10) || 1, 1), opportunities.length) - 1;
  const opp = opportunities[oi];
  const intent = pick(k.keyword_intent, INTENTS, 'Commercial');
  const nn = String(s.slot).padStart(2, '0');
  return {
    slot: s.slot,
    keyword_id: `KW-${slug}-T${ctx.tierNum}-${nn}-${ctx.run_id}`,
    prompt_id: `${slug}-T${ctx.tierNum}-${CATCODE[s.prompt_category]}-${intent.slice(0, 4).toUpperCase()}-${ctx.market}-${s.language === 'Arabic' ? 'AR' : 'EN'}-${nn}-${ctx.run_id}`,
    opportunity_id: opp.opportunity_id,
    opportunity_theme: opp.theme,
    keyword: str(k.keyword) || opp.search_query || opp.theme,
    keyword_intent: intent,
    icp_search_type: pick(k.icp_search_type, ICPS, 'Commercial'),
    topic_cluster: str(k.topic_cluster) || opp.theme,
    suggested_blog_topic: str(k.suggested_blog_topic),
    prompt_category: s.prompt_category, segment: s.segment, language: s.language, priority: s.priority,
    market: ctx.market
  };
});

const ai_engine = ($input.first().json || {}).choices ? 'ChatGPT (fallback)' : 'Gemini';
return [{ json: { ...ctx, ai_engine, profile: data.profile || {}, opportunities, keywords } }];

const c = $('Parse Profile').first().json;

const system = 'You write realistic questions that real buyers type into AI assistants (ChatGPT, Gemini, Perplexity, Claude, Google AI Overviews). Return ONLY valid JSON, no markdown.';

const items = c.keywords.map(k => ({
  keyword_id: k.keyword_id, category: k.prompt_category, segment: k.segment, language: k.language,
  keyword: k.keyword, intent: k.keyword_intent, icp_signal: k.icp_search_type, opportunity: k.opportunity_theme
}));

const user = `BRAND: ${c.brand}
WEBSITE: ${c.website}
TIER: ${c.tier}
MARKET: ${c.market} (${c.locationHint})
BUSINESS SUMMARY: ${JSON.stringify(c.profile.summary || '')}

Write exactly ${items.length} prompts, one per item below. Each prompt is what a buyer would type into an AI engine: 1-2 natural, specific sentences, in the item's language (Arabic items must be natural Arabic, not translated word-for-word).
Rules by category:
- Brand Direct Queries: ask about the brand "${c.brand}" directly (reputation, products, ordering, comparison with alternatives).
- KSA Category Intent: category benchmark question with a ${c.market} city or country; NEVER name the brand.
- Executive Gifting: decision-maker / VIP / seasonal or cultural angle (Ramadan, Eid, National Day, year-end where relevant); NEVER name the brand.
- Problem-Solution: describe the buyer's problem and ask for solutions or suppliers; NEVER name the brand.
Match the item's intent: Informational = learning, Commercial = comparing/shortlisting, Transactional = ready to buy/quote. Reflect the icp_signal (Seasonal, Cultural, Comparison, Direct answer, Commercial). Do not invent facts or claims.

ITEMS: ${JSON.stringify(items)}

Return JSON: {"prompts":[{"keyword_id":"","prompt_text":""}]}`;

const OPENAI_MODEL = 'gpt-4o-mini'; // change here if you prefer another OpenAI model
const openai_body = { model: OPENAI_MODEL, temperature: 0.7, max_tokens: 6000, response_format: { type: 'json_object' },
  messages: [{ role: 'system', content: system }, { role: 'user', content: user }] };

return [{ json: { ...c, openai_body, body: {
  systemInstruction: { parts: [{ text: system }] },
  contents: [{ role: 'user', parts: [{ text: user }] }],
  generationConfig: { temperature: 0.8, maxOutputTokens: 16000, responseMimeType: 'application/json', thinkingConfig: { thinkingLevel: 'low' } }
}}}];

const c = $('Parse Profile').first().json;
const now = new Date().toISOString();

function readJson(res, label) {
  const cand = (res.candidates || [])[0] || {};
  const txt = res.choices ? String(((res.choices[0] || {}).message || {}).content || '') : ((cand.content || {}).parts || []).map(p => p.text || '').join('');
  if (!txt) throw new Error(label + ': Gemini returned no text. finishReason=' + (cand.finishReason || 'n/a') + ' feedback=' + JSON.stringify(res.promptFeedback || {}));
  const s = txt.replace(/```json|```/g, '').trim();
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a < 0 || b < 0) throw new Error(label + ': no JSON found in response');
  try { return JSON.parse(s.slice(a, b + 1)); }
  catch (e) { throw new Error(label + ': invalid JSON (' + (cand.finishReason || '') + ') ' + e.message); }
}

// Gemini 2 is allowed to fail: keywords and opportunities are already saved, so fall back to draft prompts.
const byId = {};
let aiError = '';
try {
  const res = $input.first().json || {};
  if (res.error) throw new Error(typeof res.error === 'string' ? res.error : JSON.stringify(res.error));
  const data = readJson(res, 'Prompts');
  (data.prompts || []).forEach(p => { if (p && p.keyword_id) byId[p.keyword_id] = String(p.prompt_text || '').trim(); });
} catch (e) { aiError = String(e.message || e).slice(0, 300); }

const res0 = $input.first().json || {};
const engine2 = aiError ? 'draft fallback' : (res0.choices ? 'ChatGPT (fallback)' : 'Gemini');
const engines = 'Analysis: ' + (c.ai_engine || 'Gemini') + ' | Prompts: ' + engine2;
let fallback = 0;
const prompts = c.keywords.map(k => {
  let t = byId[k.keyword_id];
  const ok = !!t;
  if (!ok) { fallback++; t = k.language === 'Arabic' ? k.keyword : `What are the best options for ${k.keyword}?`; }
  return {
    prompt_id: k.prompt_id, created_at: now, brand: c.brand, website: c.website, tier: c.tier,
    category: k.prompt_category, icp_search_type: k.icp_search_type, keyword_intent: k.keyword_intent,
    market: k.market, language: k.language, segment: k.segment, target_keyword: k.keyword,
    prompt_text: t, status: ok ? 'Pending scan' : 'Needs rewrite', priority: k.priority, keyword_id: k.keyword_id
  };
});

const response = {
  success: true, run_id: c.run_id, brand: c.brand, tier: c.tier, market: c.market,
  counts: { opportunities: c.opportunities.length, keywords: c.keywords.length, prompts: prompts.length, fallback_prompts: fallback },
  ai_error: aiError, engines, prompts
};
return [{ json: { run_id: c.run_id, prompts, response } }];

const c = $('Parse Profile').first().json;
const now = new Date().toISOString();
return c.opportunities.map(o => ({ json: {
  opportunity_id: o.opportunity_id, created_at: now, brand: c.brand, website: c.website, tier: c.tier,
  theme: o.theme, buyer_intent: o.buyer_intent, audience: o.audience, market: c.market, language: c.language,
  search_query: o.search_query, seasonal: o.seasonal, cultural: o.cultural, competitor: o.competitor, gap: o.gap, status: 'Pending'
}}));

const c = $('Parse Profile').first().json;
const now = new Date().toISOString();
return c.keywords.map(k => ({ json: {
  keyword_id: k.keyword_id, created_at: now, brand: c.brand, website: c.website, tier: c.tier,
  market: k.market, language: k.language, keyword: k.keyword, intent: k.keyword_intent,
  icp_search_type: k.icp_search_type, volume_estimate: '[TO VERIFY]', difficulty: '[TO VERIFY]',
  content_pillar: k.topic_cluster, suggested_blog_topic: k.suggested_blog_topic, ai_cited_content: '',
  status: 'Pending', opportunity_id: k.opportunity_id, priority: k.priority
}}));

const c = $('Parse Prompts').first().json;
const summary = { run_id: c.run_id, engines: c.engines, ai_engine: c.ai_engine, counts: { opportunities: c.opportunities.length, keywords: c.keywords.length, prompts: c.prompts.length }, response: c };
const rows = c.prompts.map(p => ({ json: p }));
return [rows, [summary]];
